    public async Task<Result<HotelRoomDto>> GetRoomNumber(string number, CancellationToken ct) => PropertyId is not { } p ? Result<HotelRoomDto>.Failure(Error.Authorization("HOTEL_ROOM_PROPERTY_MISMATCH", "Property scope is invalid.")) : await repository.GetRoomByNumberAsync(p, number, ct) is { } x ? Result<HotelRoomDto>.Success(x) : Result<HotelRoomDto>.Failure(Error.Business("HOTEL_ROOM_NOT_FOUND", "Hotel room was not found."));
